/* @author MILO-GAO(高振銘)@2020 */ package page2020.data;import java.io.FileOutputStream;import java.io.OutputStreamWriter;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.nio.file.Path;import java.nio.file.Paths;import java.util.List;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.scheduling.annotation.Async;import org.springframework.stereotype.Service;import page2020.core.Log;@Servicepublic class DataAsync {	private static Logger log = LoggerFactory.getLogger(DataAsync.class);	@Async	public void write(TableData source) {		try {			Path dir = Paths.get("data" + source.getAppName());			Files.createDirectories(dir);			String filename = source.getUsername().replaceAll(" ", "") + ".csv";			Path file = Paths.get("data" + source.getAppName() + "/" + filename);			Files.deleteIfExists(file);			FileOutputStream out = new FileOutputStream(file.toString());			OutputStreamWriter writer = new OutputStreamWriter(out, StandardCharsets.UTF_8);			List<List<Object>> data = source.getData();			int length = data.size();			int columns = data.get(0).size();			int beginIndex = source.isSerial() ? 1 : 0;			for (int i=0; i < length; i++) {				List<Object> row = data.get(i);				StringBuilder sb1 = new StringBuilder();				for (int j = beginIndex; j < columns; j++) {					if (j != beginIndex) {						sb1.append("\t");					}					sb1.append(row.get(j));				}				writer.write(sb1.append("\r").toString());			}			writer.close();			if (Log.data) {				log.info("write: file='" + file.toString() + "', data=" + length);			}		} catch (Exception ex) {			log.error("write: " + ex.toString());		}	}}